-- Case 00 · Profile the sources before analysing them
--
-- Row counts, date ranges and key null rates for every table the cases read.
-- Run first: the analysis windows in cases 03, 04 and 06 assume theLook covers
-- 2023-01 to 2025-12, and the GA4 sample covers 2020-11-01 to 2021-01-31.
-- (theLook is synthetic and regenerated by Google, so its counts change
-- between runs; the date of each run is recorded in results/run_record.json.)

WITH ga4 AS (
  SELECT
    event_date,
    user_pseudo_id,
    (SELECT ep.value.int_value FROM UNNEST(event_params) AS ep
     WHERE ep.key = 'ga_session_id') AS ga_session_id
  FROM {{ga4_events}}
)

SELECT 'ga4 events' AS source,
       COUNT(*) AS row_count,
       CAST(MIN(PARSE_DATE('%Y%m%d', event_date)) AS STRING) AS first_date,
       CAST(MAX(PARSE_DATE('%Y%m%d', event_date)) AS STRING) AS last_date,
       COUNT(DISTINCT user_pseudo_id) AS distinct_ids,
       SAFE_DIVIDE(COUNTIF(ga_session_id IS NULL), COUNT(*)) AS share_null_key
FROM ga4

UNION ALL
SELECT 'thelook users', COUNT(*), CAST(MIN(DATE(created_at)) AS STRING), CAST(MAX(DATE(created_at)) AS STRING),
       COUNT(DISTINCT id), SAFE_DIVIDE(COUNTIF(traffic_source IS NULL), COUNT(*))
FROM {{thelook.users}}

UNION ALL
SELECT 'thelook orders', COUNT(*), CAST(MIN(DATE(created_at)) AS STRING), CAST(MAX(DATE(created_at)) AS STRING),
       COUNT(DISTINCT user_id), SAFE_DIVIDE(COUNTIF(user_id IS NULL), COUNT(*))
FROM {{thelook.orders}}

UNION ALL
SELECT 'thelook order_items', COUNT(*), CAST(MIN(DATE(created_at)) AS STRING), CAST(MAX(DATE(created_at)) AS STRING),
       COUNT(DISTINCT order_id), SAFE_DIVIDE(COUNTIF(sale_price IS NULL), COUNT(*))
FROM {{thelook.order_items}}

UNION ALL
SELECT 'thelook events', COUNT(*), CAST(MIN(DATE(created_at)) AS STRING), CAST(MAX(DATE(created_at)) AS STRING),
       COUNT(DISTINCT user_id), SAFE_DIVIDE(COUNTIF(user_id IS NULL), COUNT(*))
FROM {{thelook.events}}
